def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.pop()
                cells.append((x, y))
                for a, b in ((x+1,y),(x-1,y),(x,y+1),(x,y-1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == color and (a,b) not in seen:
                        seen.add((a,b))
                        q.append((a,b))
            r0 = min(x for x, y in cells); r1 = max(x for x, y in cells)
            c0 = min(y for x, y in cells); c1 = max(y for x, y in cells)
            ih, iw = r1-r0-1, c1-c0-1
            if ih <= 0 or iw <= 0:
                continue
            fill = 2 if ih % 2 == 0 and iw % 2 == 0 else 7
            for x in range(r0+1, r1):
                for y in range(c0+1, c1):
                    if grid[x][y] != color:
                        out[x][y] = fill
    return out
